import functools

@functools.lru_cache(None)
def solve(board, turn):
    # turn: 0 for Alice (maximize U), 1 for Bob (minimize U)
    # board: tuple of booleans, True if occupied

    # Find all possible moves (adjacent empty squares)
    moves = []
    for i in range(len(board) - 1):
        if not board[i] and not board[i+1]:
            moves.append((i, i+1))

    if not moves:
        # Game ends, count uncovered squares
        return sum(1 for x in board if not x)

    if turn == 0: # Alice's turn (Maximize U)
        best_u = -1
        for move in moves:
            new_board = list(board)
            new_board[move[0]] = True
            new_board[move[1]] = True
            u = solve(tuple(new_board), 1)
            if u > best_u:
                best_u = u
        return best_u
    else: # Bob's turn (Minimize U)
        best_u = float('inf')
        for move in moves:
            new_board = list(board)
            new_board[move[0]] = True
            new_board[move[1]] = True
            u = solve(tuple(new_board), 0)
            if u < best_u:
                best_u = u
        return best_u

for n in range(1, 21):
    board = tuple([False] * n)
    print(f"N={n}: f({n})={solve(board, 0)}")

