import functools

@functools.lru_cache(None)
def solve_segments(segments, turn):
    # segments: tuple of lengths of empty segments, sorted
    # turn: 0 for Alice (max U), 1 for Bob (min U)

    # Find all possible moves
    moves = []
    for i, length in enumerate(segments):
        if length >= 2:
            # A move in a segment of length 'length' splits it into two segments of length 'j' and 'length-j-2'
            for j in range(length - 1):
                # This is not quite right. A tile covers two adjacent squares.
                # If we place a tile at (k, k+1), the segment of length L is split into
                # a segment of length k and a segment of length L-k-2.
                # k can range from 0 to L-2.
                pass

    # Let's rewrite the move generation
    possible_moves = []
    for i, length in enumerate(segments):
        if length >= 2:
            for k in range(length - 1):
                # Split segment i into lengths k and length-k-2
                new_segments = list(segments)
                new_segments.pop(i)
                if k > 0:
                    new_segments.append(k)
                if length - k - 2 > 0:
                    new_segments.append(length - k - 2)
                possible_moves.append(tuple(sorted(new_segments)))

    if not possible_moves:
        # Game ends. U is the sum of the remaining segments' lengths
        # but wait, the game ends when no segment has length >= 2.
        # So all remaining segments have length 0 or 1.
        # The number of uncovered squares is the sum of lengths of segments.
        return sum(segments)

    if turn == 0: # Alice's turn (Maximize U)
        best_u = -1
        for next_segments in possible_moves:
            u = solve_segments(next_segments, 1)
            if u > best_u:
                best_u = u
        return best_u
    else: # Bob's turn (Minimize U)
        best_u = float('inf')
        for next_segments in possible_moves:
            u = solve_segments(next_segments, 0)
            if u < best_u:
                best_u = u
        return best_u

